#!/bin/sh
# Fetch the images of docker-compose.yaml by digest into images/ (generated by hydo compose; hydo-build
# never pulls). Needs hydo-fetch-image (it comes with hydo) and network access, once.
# It fetches the images this machine builds: x86_64 on Linux, arm64 on a Mac. Name
# x86_64, arm64 or all as the argument to choose (sh fetch-images.sh all).
set -eu
cd "$(dirname "$0")"
A=${1:-}
[ -n "$A" ] || case "$(uname -s)" in Darwin) A=arm64;; *) A=x86_64;; esac
case "$A" in x86_64|arm64|all) ;; *) echo "fetch-images.sh: x86_64, arm64 or all (got $A)" >&2; exit 2;; esac
F=${HYDO_FETCH_IMAGE:-$(command -v hydo-fetch-image || true)}
[ -n "$F" ] || { echo "fetch-images.sh: hydo-fetch-image not found (put hydo's bin directory on PATH, or set HYDO_FETCH_IMAGE)" >&2; exit 1; }
mkdir -p images
[ "$A" = x86_64 ] || [ -e images/cockroachdb-cockroach-v26.4.1-arm64-oci ] || "$F" docker.io/cockroachdb/cockroach sha256:a1bde0884057cd9edd9cfccf2c88d943e4e8bdbcacc9558167067bc7bb72d53f cockroachdb/cockroach:v26.4.1 images/cockroachdb-cockroach-v26.4.1-arm64-oci
[ "$A" = arm64 ] || [ -f images/cockroachdb-cockroach-v26.4.1-amd64.docker.tar ] || "$F" docker.io/cockroachdb/cockroach sha256:de1c2ef57bc2b5b7e553ab68e0cd4217a948ab26eae471b63ffea00127f8e0f6 cockroachdb/cockroach:v26.4.1 images/cockroachdb-cockroach-v26.4.1-amd64.docker.tar
[ "$A" = arm64 ] || ls -ld images/cockroachdb-cockroach-v26.4.1-amd64.docker.tar
[ "$A" = x86_64 ] || ls -ld images/cockroachdb-cockroach-v26.4.1-arm64-oci
